import { isStopped } from "../runtime/operation";
import { alternatives } from "./alternatives";
import { createRecipeSelectors } from "./recipe-selectors";
import { createRecipeControls } from "./recipe-controls";
import { createRecipeValues } from "./recipe-values";
import { createRecipeFields } from "./recipe-fields";
import { createRecipeActions } from "./recipe-actions";
// The config-driven reader. adapters/recipes/<ATS>.json (generated by
// tools/convert_ats_config.py) describes one ATS as data: url match
// patterns, fields that name the fact they take and the selectors and fill
// method that take it, repeated groups (education, experience) with an add
// button and nested fields, flow steps (open the form, expand a section,
// save it), the selectors that find custom questions and how to answer
// them, and the apply, continue, submit and success paths. This file
// interprets that data for the matching ATS and exposes the same reader
// interface the hand-written readers do, plus a step model for forms that
// span pages.
/** @param {import("./types").AdapterContext} context */
export function createRecipeAdapter(configs, context) {
  const sleep = (ms) => context.operation.sleep(ms);
  const { clean, list, matchesPattern, expand, $x, text, visible, first, waitFirst, anyGroup } = createRecipeSelectors(context.operation);

  // The config for this page: by url, or by the marks an embedded form
  // leaves on a host of its own (an iframe or a form posting to the ATS).
  // A url the table excludes (a confirmation page, a listing) gets nothing.
  // `let`, not `const`: the bundled table is the fallback, and the content
  // script may swap in the table the API published for this adapter before a
  // fill (useConfig below). Every reader function reads recipeConfig when called, so
  // a swap takes effect on the next read of the form.
  let recipeConfig =
    configs.find((c) => c.matches.some((m) => matchesPattern(m, location.href))) ||
    configs.find((c) => anyGroup(c.embeddedPaths));
  if (!recipeConfig) return;
  if (list(recipeConfig.urlsExcluded).some((g) => matchesPattern(g, location.href))) return;

  const { events, clickOn, chooseNative, checkOrRadio, uploadFile, typeInto, pickOption, runMethod } = createRecipeControls(context, () => recipeConfig, sleep, (message) => note(message));
  const { mapPath, candidates, parseDate, todayParts, formatDate, entryValue } = createRecipeValues(context, list);

  // Fields live inside the container when the table says so (a Greenhouse
  // form beside a job board, a Workday frame beside its chrome).
  const container = () => first(recipeConfig.container || [], {}, document, true)?.el || null;
  const scope = () => container() || (recipeConfig.containerRequired ? null : document);

  let trace = null;
  const note = (msg) => {
    if (trace) trace.push(msg);
  };
  // The table's action list: each step waits up to `time` for its path,
  // skips itself on a failed `condition` or an empty value it needs, and
  // either fires an event, waits for its path to be removed, picks the
  // option its `valuePath` names, or runs a method on what it found.
  const { runActions, resetSeenOptions, getSeenOptions } = createRecipeActions({ context, sleep, clean, text, visible, list, $x, expand, first, waitFirst, candidates, pickOption, runMethod, events, note });

  // ---- fields --------------------------------------------------------------
  const fieldKind = (fact) => {
    if (fact === "resume") return "file";
    if (fact === "step") return "step";
    if (/^(education|experience)$/.test(fact || "")) return "group";
    if (/^(work_authorized|needs_sponsorship|yes|no|consent)$/.test(fact || "")) return "yesno";
    if (/^(gender|ethnicity|hispanic|veteran|disability|referral_source|country|state|degree|phone_type|phone_country)$/.test(fact || "")) return "select";
    return "text";
  };
  const isGroup = (v) => !!(v.group || v.array || v.inputSelectors);
  const isManual = (spec) => spec.variants.length > 0 && spec.variants.every((v) => v.manual);
  const fieldPaths = (spec) => spec.variants.filter((v) => !isGroup(v)).flatMap((v) => v.paths || []);
  const { questionFields } = createRecipeFields(() => recipeConfig, list, $x, expand, visible, text, clean, isGroup);
  const submitElement = () => first(recipeConfig.submit || [], {}, document, true)?.el || null;
  // A group's entry containers are numbered by the page, and the number is
  // not always the entry's position: Workday numbers a block from a running
  // counter (a fresh block was workExperience-6, report 8). Every number
  // below this is tried.
  const ENTRY_NUMBERS = 30;

  function groupPresent(spec, root) {
    return spec.variants.some((v) => isGroup(v) && (first(v.addButtonPath || [], {}, root) || first(v.containerPath || [], { index: 0 }, root) || countEntries(v) > 0));
  }
  // How many entries a group shows: its containers under any number the
  // page gave them, or the rows its confirm path names.
  function countEntries(v) {
    const found = new Set();
    for (const path of [...list(v.containerPath), ...list(v.confirmAddedPath)]) {
      for (let n = 0; n < ENTRY_NUMBERS; n++) for (const el of $x(expand(path, { index: n }))) found.add(el);
    }
    return found.size;
  }
  // Steps are the table's flow: open the form, expand a section, save it.
  // They run in table order around the fields they sit between, are never
  // read to the panel and never asked of the model, and a step whose path
  // is not on the page is skipped.
  const ranSteps = new Set();
  async function runStep(spec, root) {
    ranSteps.add(spec.name);
    for (const v of spec.variants) {
      if (isGroup(v) || v.manual) continue;
      const found = first(v.paths, { value: "" }, root, v.hidden === true);
      if (!found || found.el === submitElement()) continue;
      await runMethod(v.method, found.el, "", null, v.eventOptions);
      await runActions(v.actions, { inputPath: found.path, value: "" }, root, found.el, "", null);
      return true;
    }
    return false;
  }
  async function stepsBefore(index, root) {
    for (let i = 0; i < index; i++) {
      const f = recipeConfig.fields[i];
      if (fieldKind(f.fact) === "step" && !ranSteps.has(f.name)) await runStep(f, root);
    }
  }
  const lastFieldIndex = () => {
    let last = -1;
    recipeConfig.fields.forEach((f, i) => {
      if (fieldKind(f.fact) !== "step") last = i;
    });
    return last;
  };

  function factFields(root) {
    const out = [];
    recipeConfig.fields.forEach((f, i) => {
      const kind = fieldKind(f.fact);
      if (kind === "step") return;
      const base = { key: `fact:${f.name}`, label: f.name.replace(/_/g, " "), kind, required: false, options: [], fact: f.fact, _spec: f, _index: i, _person: isManual(f) };
      if (kind === "group") {
        if (groupPresent(f, root)) out.push({ ...base, _el: null });
        return;
      }
      const probe = first(fieldPaths(f), { value: "" }, root, f.variants.some((v) => v.hidden === true));
      if (probe) out.push({ ...base, _el: probe.el });
    });
    return out;
  }
  // A form behind an Apply button (or an "apply manually" choice): the
  // button is clicked and the fields waited for. Never a submit.
  async function openForm() {
    for (const paths of [recipeConfig.applyOptionPaths, recipeConfig.applyButtonPaths]) {
      const btn = first(paths || [], {}, document, false);
      if (!btn || btn.el === submitElement()) continue;
      clickOn(btn.el, { noBlur: true });
      const deadline = Date.now() + 8000;
      while (Date.now() < deadline && !anyField()) await sleep(200);
    }
  }
  const excluded = () => anyGroup(recipeConfig.pathsExcluded);
  const domOrder = (a, b) => {
    const x = a._el || a._box;
    const y = b._el || b._box;
    if (!x || !y || x === y) return 0;
    return x.compareDocumentPosition(y) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1;
  };
  async function read() {
    await context.operation.checkpoint();
    ranSteps.clear();
    if (excluded()) return [];
    if (!anyField()) await openForm();
    const root = scope();
    if (!root) return [];
    const facts = factFields(root);
    const out = [...facts, ...questionFields(new Set(facts.map((f) => f._el).filter(Boolean)), root)];
    return recipeConfig.orderByDomPosition === false ? out : out.sort(domOrder);
  }

  const optionLabel = (i) => clean(i.closest("label")?.innerText || document.querySelector(`label[for="${CSS.escape(i.id)}"]`)?.innerText || i.value);
  function current(field) {
    if (field.kind === "group") {
      const n = field._spec.variants
        .filter(isGroup)
        .reduce((acc, v) => acc + countEntries(v), 0);
      return n ? `${n} entries` : "";
    }
    if (field._options && field._options.length) {
      const selected = (o) =>
        field._selectedPath
          ? list(field._selectedPath).some((p) => $x(p, o.el).length)
          : o.el.checked || o.el.getAttribute("aria-selected") === "true" || o.el.getAttribute("aria-checked") === "true";
      const on = field._options.filter(selected);
      if (on.length || !field._el) return on.map((o) => o.text).join(" | ");
    }
    // A custom widget shows its value somewhere other than an input.
    if (field._textPath && field._box) {
      const t = list(field._textPath).map((p) => text($x(p, field._box)[0])).find((s) => s && s.trim());
      if (t) return clean(t);
    }
    const el = field._el;
    if (!el || !el.isConnected) return "";
    if (el.type === "file") return el.files && el.files.length ? el.files[0].name : "";
    if (el.tagName === "SELECT") return el.selectedOptions[0]?.text.trim() || "";
    if (el.type === "radio" || el.type === "checkbox") {
      const group = el.name ? [...document.querySelectorAll(`input[name="${CSS.escape(el.name)}"]`)] : [el];
      return group.filter((i) => i.checked).map(optionLabel).join(" | ");
    }
    return el.value || "";
  }

  async function fillVariants(variants, value, file, root, ctx) {
    const wants = alternatives(value);
    for (const want of wants.length ? wants : [""]) {
      for (const [index, v] of variants.entries()) {
        if (isGroup(v) || v.manual) continue;
        for (const candidate of candidates(v, ctx, want)) {
          // A path per value, or the one path with the value in it.
          const paths = v.valuePathMap ? mapPath(v.valuePathMap, candidate) : v.paths;
          if (!paths) continue;
          const vctx = { ...ctx, value: candidate, raw: want };
          const found = await waitFirst(paths, vctx, root, v.hidden === true, v.time || 0);
          if (!found) {
            note(`variant ${index}: anchor not on page for "${candidate}"`);
            continue;
          }
          let ok;
          try {
            if (v.valuePath) {
              const opt = await waitFirst(v.valuePath, { ...vctx, inputPath: found.path }, root, true, v.valueElementTime || 300);
              ok = opt ? pickOption(opt.el) : false;
            } else if (!v.method && v.actions && v.actions.length) {
              // A variant with actions and no method of its own: the anchor is
              // only the %INPUTPATH% the actions refer to, and the actions do
              // all the work. Clicking it first opened Workday's dropdown so
              // the recipe's own click closed it again (2026-09-08).
              ok = true;
            } else {
              ok = await runMethod(v.method, found.el, candidate, file, v.eventOptions);
            }
            const acted = await runActions(v.actions, { ...vctx, inputPath: found.path }, root, found.el, candidate, file);
            if (ok && acted) {
              note(`variant ${index}: took "${candidate}"`);
              return true;
            }
            note(`variant ${index}: ${ok ? "actions failed" : "method failed"} for "${candidate}"`);
          } catch (e) {
            if (isStopped(e)) throw e;
            // One variant's error is that variant's; the next may work, and
            // the trace says what happened.
            note(`variant ${index}: ${String(e)}`);
          }
        }
      }
    }
    return false;
  }

  // One entry per profile row: add a container when the page has fewer than
  // the row needs, then every nested field the row has a value for.
  async function fillGroup(group, items, file, fact, asName = null, parentRoot = null, entryNumber = null) {
    const rows = group.limit ? items.slice(0, group.limit) : items;
    const ordered = group.reverse ? [...rows].reverse() : rows;
    let filledAny = false;
    for (let i = 0; i < ordered.length; i++) {
      const item = ordered[i];
      const ctx = { index: i, length: ordered.length, item, fact };
      if (i && recipeConfig.fillInputGroupInterval) await sleep(recipeConfig.fillInputGroupInterval);
      // The entry containers on the page, in page order, whichever number
      // the page gave each (ENTRY_NUMBERS): the i-th container found is the
      // i-th entry.
      const containerPaths = list(group.containerPath);
      // Each container remembers the number it was found under: a recipe
      // inside the entry may name the entry by number too (Workday's
      // field-of-study click names education-%NUMBER0%), and the page's own
      // number is the one that matches, not the entry's position.
      const numberOf = new Map();
      const allContainers = () => {
        numberOf.clear();
        // Paths are alternatives, not separate entries. Combining them can
        // count both an entry and its wrapper as two profile rows.
        for (const path of containerPaths) {
          for (let n = 0; n < ENTRY_NUMBERS; n++) for (const el of $x(expand(path, { ...ctx, index: n }))) if (!numberOf.has(el)) numberOf.set(el, n);
          if (numberOf.size) break;
        }
        return [...numberOf.keys()].sort((a, b) => (a.compareDocumentPosition(b) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1));
      };
      // A nested group of one widget (company inside an experience, school
      // inside an education) has no container of its own: it fills inside
      // its parent's entry (report 12: company, school and field of study
      // never ran because it had none).
      let containers = containerPaths.length ? allContainers() : parentRoot ? [parentRoot] : [];
      if (containerPaths.length && containers.length <= i) {
        const add = first(group.addButtonPath || [], ctx);
        if (!add) {
          note(`${fact} entry ${i + 1}: no add button`);
          break;
        }
        clickOn(add.el, { noBlur: true });
        const deadline = Date.now() + (group.time || 4000);
        while (Date.now() < deadline) {
          containers = allContainers();
          if (containers.length > i) break;
          await sleep(150);
        }
        if (containers.length <= i) {
          note(`${fact} entry ${i + 1}: add clicked, no container appeared`);
          break;
        }
      }
      // Inside the entry's container or not at all: against the document
      // the same selector matches the form's own fields (Workable's
      // Summary box).
      const root = containers[i];
      if (!root) break;
      const pageNumber = entryNumber ?? numberOf.get(root) ?? i;
      const entryCtx = { ...ctx, index: pageNumber };
      note(`${fact} entry ${i + 1}: filling${pageNumber !== i ? ` (page number ${pageNumber + 1})` : ""}`);
      for (const nested of group.fields || []) {
        // A nested group of one field ("major" holding "name") takes the
        // outer name's value: the inner "name" is the widget, not the fact.
        const value = entryValue(asName || nested.name, item, fact);
        if (value === null) continue;
        for (const v of nested.variants) {
          if (isGroup(v)) await fillGroup({ ...v, containerPath: v.containerPath || [] }, [item], file, fact, asName || nested.name, root, pageNumber);
        }
        const plain = nested.variants.filter((v) => !isGroup(v));
        if (plain.length) {
          try {
            // A widget that takes several values (Workday's field of study
            // is a multi-select: two majors, two picks) takes every
            // alternative; any other takes the first that lands.
            const multi = plain.some((v) => list(v.paths).some((p) => /multiselect/i.test(p)));
            const parts = multi ? String(value).split("|").map((x) => x.trim()).filter(Boolean) : [String(value)];
            let took = false;
            for (const part of parts) took = (await fillVariants(plain, part, file, root, entryCtx)) || took;
            note(`${nested.name} = "${String(value).slice(0, 40)}": ${took ? "took" : "not taken"}${multi ? ` (${parts.length} picks)` : ""}`);
          } catch (e) {
            if (isStopped(e)) throw e;
            note(`${nested.name}: ${String(e)}`);
          }
        }
        if (recipeConfig.fillInputInterval) await sleep(recipeConfig.fillInputInterval);
      }
      filledAny = true;
      if (list(group.confirmAddedPath).length) {
        const deadline = Date.now() + 3000;
        while (Date.now() < deadline && !first(group.confirmAddedPath, ctx)) await sleep(150);
      }
    }
    return filledAny;
  }

  async function fill(field, value, file) {
    await context.operation.checkpoint();
    const root = scope() || document;
    trace = field._trace = [];
    resetSeenOptions();
    try {
      return await (field._spec ? fillFact(field, value, file, root) : fillQuestion(field, value, file));
    } finally {
      // The options a search showed and nothing matched: the panel's model
      // call gets them and its pick comes back through fill as an exact.
      const seenOptions = getSeenOptions();
      if (seenOptions && seenOptions.length) field._seen = seenOptions;
    }
  }
  // A field the table names: the flow steps the table puts before it, then
  // the field, then the steps that close the form when it is the last field.
  async function fillFact(field, value, file, root) {
    await stepsBefore(field._index, root);
    const ok = await putFact(field, value, file, root);
    if (field._index === lastFieldIndex()) await stepsBefore(recipeConfig.fields.length, root);
    if (recipeConfig.fillInputInterval) await sleep(recipeConfig.fillInputInterval);
    return ok;
  }
  async function putFact(field, value, file, root) {
    if (field._person) return false;
    if (field.kind === "group") {
      const items = (context.profile[field.fact] || []).filter((x) => x && (x.company || x.school));
      let ok = false;
      if (items.length) for (const v of field._spec.variants) if (isGroup(v)) ok = (await fillGroup(v, items, file, field.fact)) || ok;
      return ok;
    }
    // A file field carries the file, not a value; its recipe runs with
    // the file (report 12: the resume never ran on a null value).
    if (field.kind === "file") return file ? fillVariants(field._spec.variants, "", file, root, {}) : false;
    // A date the field names a format for: today's date is ours to
    // supply, a birthday must come with the value.
    let v = value;
    if (field.fact === "today") v = formatDate(field._spec.name, parseDate(value) || todayParts());
    else if (field.fact === "birthday") v = formatDate(field._spec.name, parseDate(value));
    return v == null ? false : fillVariants(field._spec.variants, v, file, root, {});
  }
  // A custom question the table's selectors found on the page.
  async function fillQuestion(field, value, file) {
    const wants = alternatives(value);
    if (field._q && field._q.fillActions && (field._options?.length || field._fillEmpty) && !field._el?.tagName?.match(/SELECT|TEXTAREA/)) {
      // A custom choice with its own recipe: open the list, click the option.
      // A recipe that needs no value (a "today" button) runs once with none.
      for (const want of wants.length ? wants : field._fillEmpty ? [""] : []) {
        if (await runActions(field._q.fillActions, { value: want }, field._box, field._el, want, file)) {
          await sleep(200);
          if (current(field) || field._fillEmpty) return true;
        }
      }
    }
    if (field._options && field._options.length && field._options[0].el.type) {
      let took = false;
      const lowered = wants.map((w) => w.toLowerCase());
      for (const o of field._options) {
        if (lowered.includes(o.text.toLowerCase()) && !o.el.checked) {
          checkOrRadio(o.el, true);
          took = true;
          if (o.el.type === "radio") break;
        }
      }
      if (took) return true;
    }
    const el = field._el;
    if (!el || !el.isConnected) return false;
    let ok;
    if (field.kind === "file") ok = uploadFile(el, file);
    else if (el.tagName === "SELECT") ok = chooseNative(el, value);
    else if (el.type === "radio" || el.type === "checkbox") ok = checkOrRadio(el, true);
    else ok = typeInto(el, wants[0] ?? "", null, recipeConfig.defaultMethod === "default");
    if (recipeConfig.fillInputInterval) await sleep(recipeConfig.fillInputInterval);
    return ok;
  }

  const buttonAt = (paths) => {
    const node = first(paths || [])?.el;
    return node instanceof HTMLElement ? node : null;
  };
  const nextButton = () => buttonAt(recipeConfig.continue);
  const submitButton = () => buttonAt(recipeConfig.submit);
  // A modal the ATS raises after submit (a chatbot with more questions)
  // means the application is not in yet.
  const submitted = () => !first(recipeConfig.deferSubmissionModalPaths || []) && (recipeConfig.success || []).some((p) => $x(p).length > 0);
  // The fields the page marks invalid, within the scope the table names.
  const errors = () => {
    const roots = list(recipeConfig.validationScopePaths).flatMap((p) => $x(p));
    const within = roots.length ? roots : [document];
    return within
      .flatMap((r) => [...r.querySelectorAll('[aria-invalid="true"], .error input, .has-error input')])
      .map((el) => clean(el.labels?.[0]?.innerText || el.getAttribute("aria-label") || el.name || el.id));
  };
  const anyField = () => {
    const root = scope();
    if (!root) return false;
    return (
      !!first(recipeConfig.fields.filter((f) => fieldKind(f.fact) !== "step").flatMap(fieldPaths), { value: "" }, root) ||
      recipeConfig.fields.some((f) => fieldKind(f.fact) === "group" && groupPresent(f, root)) ||
      (recipeConfig.questions || []).some((q) => list(q.fieldPath).some((p) => $x(p, root).some(visible)))
    );
  };
  const applyButton = () => !!first(recipeConfig.applyButtonPaths || [], {}, document, false) || !!first(recipeConfig.applyOptionPaths || [], {}, document, false);
  const ready = () => !excluded() && (anyField() || applyButton());

  return {
    host: recipeConfig.name.toLowerCase(),
    ready,
    read,
    fill,
    current,
    submitButton,
    nextButton,
    submitted,
    errors,
    // A published table for THIS adapter replaces the bundled one for the
    // fills that follow; any other table is refused and the bundled copy
    // stays. Returns whether the swap happened.
    useConfig(next) {
      if (!next || typeof next !== "object" || typeof next.name !== "string") return false;
      if (next.name.toLowerCase() !== recipeConfig.name.toLowerCase()) return false;
      if (!Array.isArray(next.matches) || !Array.isArray(next.fields)) return false;
      recipeConfig = next;
      return true;
    },
  };
}
